"""PNG/JPEG C2PA and AI metadata strip — from watermarks-remover image_meta.py v0.7.0."""

from __future__ import annotations

import struct
import zlib

PNG_SIG = b"\x89PNG\r\n\x1a\n"

JPEG_SOI = b"\xff\xd8"

MAX_PNG_TEXT_DECOMPRESSED_BYTES = 1 << 20

C2PA_MARKERS = (
    b"c2pa",
    b"C2PA",
    b"jumb",
    b"JUMB",
    b"c2ma",
    b"contentcredentials",
    b"contentauth",
    b"cai:",
    b"http://ns.adobe.com/xmp/InstanceID/",  # not solely C2PA
)

AI_META_HINTS = (
    b"c2pa",
    b"C2PA",
    b"contentcredentials",
    b"ContentCredentials",
    b"digitalSourceType",
    b"trainedAlgorithmicMedia",
    b"compositeWithTrainedAlgorithmicMedia",
    b"algorithmicMedia",
    b"AIGC",
    b"aigc",
    b"AI generated",
    b"Generated by",
    b"Claude",
    b"Anthropic",
    b"OpenAI",
    b"SynthID",
    b"dcterms:provenance",
)

AI_GENERATOR_PRODUCTS = (
    b"ChatGPT",
    b"DALL-E",
    b"Midjourney",
    b"Stable Diffusion",
    b"SDXL",
    b"FLUX",
    b"DreamStudio",
    b"Leonardo AI",
    b"Leonardo.Ai",
    b"Craiyon",
    b"NovelAI",
    b"Ideogram",
    b"TensorArt",
    b"Recraft",
    b"Clipdrop",
    b"DeepAI",
    b"NightCafe",
    b"Bing Image Creator",
    b"Adobe Firefly",
    b"Firefly",
    b"Gemini",
    b"Imagen",
    b"Grok",
    b"Sora",
    b"Veo",
    b"Kling",
    b"Runway",
    b"Luma",
    b"Qwen",
    b"GPT-4",
    b"GPT-5",
)

JPEG_C2PA_MARKERS = (
    b"c2pa",
    b"c2ma",
    b"contentcredentials",
    b"contentauth",
    b"cai:",
)

JPEG_COM_AI_HINTS = (
    *JPEG_C2PA_MARKERS,
    b"digitalSourceType",
    b"trainedAlgorithmicMedia",
    b"compositeWithTrainedAlgorithmicMedia",
    b"algorithmicMedia",
    b"AIGC",
    b"AI generated",
    b"Generated by AI",
    b"SynthID",
    b"dcterms:provenance",
)

_GENERATOR_TEXT_KEYS = ("software", "creator", "parameters")

class PngTextBudgetExceeded(Exception):
    """Decompressed PNG zTXt/iTXt exceeded MAX_PNG_TEXT_DECOMPRESSED_BYTES."""

def _contains_any(blob: bytes, needles: tuple[bytes, ...]) -> list[str]:
    found = []
    lower = blob.lower()
    for n in needles:
        if n.lower() in lower:
            try:
                found.append(n.decode("ascii", errors="replace"))
            except Exception:
                found.append(repr(n))
    return found

def _zlib_decompress_bounded(data: bytes) -> bytes:
    """Inflate zlib data, refusing output larger than the PNG-text budget.

    ``zlib.decompress`` has no output cap. A crafted zTXt/iTXt chunk of a
    few hundred KB can expand to hundreds of MB (then several more copies
    in the marker scan). ``decompressobj.decompress(..., max_length=)``
    stops before that allocation; callers treat ``PngTextBudgetExceeded``
    as a refused bomb, distinct from a corrupt stream (``zlib.error``).
    """
    limit = MAX_PNG_TEXT_DECOMPRESSED_BYTES
    dec = zlib.decompressobj()
    out = dec.decompress(data, max_length=limit)
    if not dec.eof and len(out) >= limit:
        raise PngTextBudgetExceeded(f"PNG text decompressed size exceeds cap ({limit} bytes)")
    extra = dec.flush()
    if extra:
        if len(out) + len(extra) > limit:
            raise PngTextBudgetExceeded(f"PNG text decompressed size exceeds cap ({limit} bytes)")
        out += extra
    return out

def _png_text_entries(payload: bytes, ctype: bytes) -> list[tuple[str, str]]:
    """Parse a PNG text-chunk payload into (key, value) pairs.

    Handles tEXt (latin-1), zTXt (zlib-compressed text), and iTXt
    (UTF-8, optionally compressed). Malformed or undecodable chunks
    yield whatever pairs are recoverable. Over-budget compressed text
    raises ``PngTextBudgetExceeded`` so inspect/clean can refuse the
    chunk without allocating it.
    """
    entries: list[tuple[str, str]] = []
    if ctype == b"tEXt":
        key, sep, text = payload.partition(b"\x00")
        if sep:
            entries.append(
                (
                    key.decode("latin-1", errors="replace"),
                    text.decode("latin-1", errors="replace"),
                )
            )
    elif ctype == b"zTXt":
        key, sep, rest = payload.partition(b"\x00")
        if not sep or len(rest) < 2:
            return entries
        try:
            text = _zlib_decompress_bounded(rest[1:])
        except zlib.error:
            return entries
        entries.append(
            (
                key.decode("latin-1", errors="replace"),
                text.decode("latin-1", errors="replace"),
            )
        )
    elif ctype == b"iTXt":
        key, sep, rest = payload.partition(b"\x00")
        if not sep or len(rest) < 4:
            return entries
        comp_flag = rest[0]
        rest = rest[2:]  # skip compression flag + method
        _lang, sep2, rest = rest.partition(b"\x00")
        if not sep2:
            return entries
        _tkey, sep3, text = rest.partition(b"\x00")
        if not sep3:
            return entries
        if comp_flag == 1:
            try:
                text = _zlib_decompress_bounded(text)
            except zlib.error:
                return entries
        entries.append(
            (
                key.decode("latin-1", errors="replace"),
                text.decode("utf-8", errors="replace"),
            )
        )
    return entries

def _generator_product_hits(entries: list[tuple[str, str]]) -> list[str]:
    """Product-name hits scoped to generator-bearing text-chunk keys.

    Returns labels like "Software=ChatGPT" (one per matching product).
    Matching is a case-insensitive substring check on the value, mirroring
    _contains_any, but only for _GENERATOR_TEXT_KEYS values.
    """
    hits: list[str] = []
    for key, value in entries:
        if key.strip().lower() not in _GENERATOR_TEXT_KEYS:
            continue
        low = value.lower()
        for product in AI_GENERATOR_PRODUCTS:
            label = product.decode("ascii", errors="replace")
            if label.lower() in low:
                hits.append(f"{key.strip()}={label}")
    return hits

def _png_text_hits(payload: bytes, ctype: bytes) -> tuple[list[str], list[str]]:
    """Return flat-marker and product-name hits from a PNG text chunk."""
    entries = _png_text_entries(payload, ctype)
    decoded = "\n".join(value for _key, value in entries).encode("utf-8")
    hits = _contains_any(payload + b"\n" + decoded, AI_META_HINTS + C2PA_MARKERS)
    return hits, _generator_product_hits(entries)

def _text_chunk_is_ai(payload: bytes, ctype: bytes) -> bool:
    """True when a PNG text chunk carries AI/C2PA markers.

    Flat markers (AI_META_HINTS + C2PA_MARKERS) match the raw payload and
    decoded text; generator product names only match generator-bearing key
    values (see _generator_product_hits).
    """
    hits, product_hits = _png_text_hits(payload, ctype)
    return bool(hits or product_hits)

def strip_png(data: bytes, *, strip_all_text: bool = True) -> tuple[bytes, list[str]]:
    if not data.startswith(PNG_SIG):
        raise ValueError("not PNG")
    actions: list[str] = []
    out = bytearray(PNG_SIG)
    pos = 8
    while pos + 8 <= len(data):
        length = struct.unpack(">I", data[pos : pos + 4])[0]
        ctype = data[pos + 4 : pos + 8]
        chunk_start = pos + 8
        chunk_end = chunk_start + length
        if chunk_end + 4 > len(data):
            # A truncated chunk (interrupted download): copy the remainder
            # verbatim instead of dropping it — dropping turned a recoverable
            # image into an unopenable husk while reporting "already clean"
            # (#170). Note it as an action so the run is never mistaken for
            # an ordinary no-op clean.
            out.extend(data[pos:])
            actions.append(
                f"kept {len(data) - pos} bytes of truncated chunk {ctype.decode('latin-1', errors='replace')} tail (file truncated)"
            )
            break
        payload = data[chunk_start:chunk_end]
        crc_bytes = data[chunk_end : chunk_end + 4]
        pos = chunk_end + 4
        name = ctype.decode("latin-1", errors="replace")

        drop = False
        if ctype in (b"eXIf", b"caBX") or ctype.startswith(b"c2"):
            drop = True
            actions.append(f"drop chunk {name}")
        elif ctype in (b"tEXt", b"zTXt", b"iTXt"):
            try:
                drop = strip_all_text or _text_chunk_is_ai(payload, ctype)
            except PngTextBudgetExceeded:
                drop = True
                actions.append(f"drop chunk {name} (decompressed text exceeds cap)")
            else:
                if drop:
                    actions.append(f"drop chunk {name}")
        elif _contains_any(ctype + payload, C2PA_MARKERS) and ctype not in (
            b"IHDR",
            b"IDAT",
            b"IEND",
            b"PLTE",
            b"tRNS",
            b"gAMA",
            b"pHYs",
            b"sRGB",
            b"cHRM",
            b"iCCP",
        ):
            drop = True
            actions.append(f"drop chunk {name} (C2PA marker in payload)")

        if not drop:
            out.extend(struct.pack(">I", length) + ctype + payload + crc_bytes)
        if ctype == b"IEND":
            break
    if not actions:
        actions.append("no PNG metadata chunks removed (already clean or none matched)")
    return bytes(out), actions

def strip_jpeg(data: bytes, *, strip_all_app: bool = True) -> tuple[bytes, list[str]]:
    if not data.startswith(JPEG_SOI):
        raise ValueError("not JPEG")
    actions: list[str] = []
    out = bytearray(JPEG_SOI)
    i = 2
    n = len(data)
    while i < n:
        if data[i] != 0xFF:
            # unexpected; copy rest
            out.extend(data[i:])
            actions.append("copied remainder after non-marker byte")
            break
        while i < n and data[i] == 0xFF:
            i += 1
        if i >= n:
            break
        marker = data[i]
        i += 1

        if marker == 0xD9:  # EOI
            out.extend(b"\xff\xd9")
            break
        if marker == 0xD8:  # nested SOI?
            continue
        if 0xD0 <= marker <= 0xD7:
            out.extend(bytes([0xFF, marker]))
            continue
        if marker == 0xDA:  # SOS — copy through end
            # need length of SOS header then entropy-coded data to EOI
            if i + 2 > n:
                break
            seglen = struct.unpack(">H", data[i : i + 2])[0]
            # Find EOI from here carefully: after SOS segment header, scan for FF D9
            # not preceded by stuffed FF 00 issues — simple approach: copy from FF DA to end
            # Reconstruct: FF DA + rest of file
            out.extend(b"\xff\xda")
            out.extend(data[i:])
            actions.append("preserved entropy-coded scan (SOS→EOF)")
            break

        if i + 2 > n:
            break
        seglen = struct.unpack(">H", data[i : i + 2])[0]
        if seglen < 2 or i + seglen > n:
            out.extend(data[i - 2 :])  # best effort
            actions.append("truncated segment; copied remainder")
            break
        payload = data[i + 2 : i + seglen]
        next_i = i + seglen

        # APP0 is JFIF — keep for compatibility unless full strip of all APP
        keep = False
        drop = False
        if 0xE0 <= marker <= 0xEF:  # APPn
            if marker == 0xEB:  # APP11 JUMBF/C2PA
                drop = True
                actions.append("drop APP11 (C2PA/JUMBF)")
            elif strip_all_app and marker != 0xE0:
                # keep APP0 (JFIF) by default
                drop = True
                actions.append(f"drop APP{marker - 0xE0}")
            elif _contains_any(payload, AI_META_HINTS + C2PA_MARKERS):
                drop = True
                actions.append(f"drop APP{marker - 0xE0} (AI/C2PA markers)")
            else:
                keep = True
        elif marker == 0xFE:  # COM
            hits = _contains_any(payload, JPEG_COM_AI_HINTS)
            if strip_all_app or hits:
                drop = True
                actions.append("drop COM comment")
            else:
                keep = True
        else:
            keep = True

        if keep and not drop:
            out.extend(bytes([0xFF, marker]))
            out.extend(data[i : i + seglen])
        i = next_i

    if not actions:
        actions.append("no JPEG APP segments removed")
    return bytes(out), actions

def detect_format(data: bytes) -> str:
    if data.startswith(PNG_SIG):
        return "png"
    if data.startswith(JPEG_SOI):
        return "jpeg"
    return "unknown"


def clean_image_bytes(data: bytes) -> tuple[bytes, list[str], str]:
    """Strip C2PA/AI metadata from PNG/JPEG bytes. Other formats returned unchanged."""
    fmt = detect_format(data)
    if fmt == "png":
        cleaned, actions = strip_png(data, strip_all_text=True)
        return cleaned, actions, fmt
    if fmt == "jpeg":
        cleaned, actions = strip_jpeg(data, strip_all_app=True)
        return cleaned, actions, fmt
    return data, [f"unsupported format ({fmt}); left unchanged"], fmt
